62	    STOMPTALK_FORCE_INLINE
63	    static uint64_t zero_mask(uint64_t word) noexcept
64	    {
65	        // Presence / first match only: borrow may mark later bytes too.
66	        // Equality uses memcmp, not this approximate mask.
67	        return (word - UINT64_C(0x0101010101010101)) & ~word & UINT64_C(0x8080808080808080);
68	    }
69	
70	    STOMPTALK_FORCE_INLINE
71	    static const char* scan_header(const char* p, const char* end, bool key, bool literal) noexcept
72	    {
73	        while (end - p >= 8)
74	        {
75	            const auto word = load(p);
76	            auto events = zero_mask(word) | zero_mask(word ^ UINT64_C(0x0a0a0a0a0a0a0a0a)) |
77	                zero_mask(word ^ UINT64_C(0x0d0d0d0d0d0d0d0d));
78	            if (key || !literal)
79	                events |= zero_mask(word ^ UINT64_C(0x3a3a3a3a3a3a3a3a));
80	            if (!literal)
81	                events |= zero_mask(word ^ UINT64_C(0x5c5c5c5c5c5c5c5c));
82	            if (events)
83	            {
84	#if defined(__BYTE_ORDER__) && __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
85	                return p + (__builtin_ctzll(events) >> 3);
86	#else
87	                break; // locate the first byte in memory order below
88	#endif
89	            }
90	            p += 8;
91	        }
92	        return scalar::scan_header(p, end, key, literal);
93	    }
94	};
95	
96	template<> struct engine<STOMPTALK_BACKEND_SCALAR> : scalar {};
97	template<> struct engine<STOMPTALK_BACKEND_SWAR> : swar {};
98	
99	} // namespace backend
100	} // namespace detail
101	} // namespace stomptalk
