1	#pragma once
2	// One core TU exposes helpers and tailcall states to the C API optimizer.
3	// Derived from 123/backup/parser.cpp: small state functions and tailcall tree.
4	#include "stomptalk/parser.hpp"
5	#include "stomptalk/antoull.hpp"
6	#include "methods.hpp"
7	#include "is_header.hpp"
8	#include <algorithm>
9	#include <cassert>
10	#include <cstdint>
11	#include <limits>
12	
13	namespace stomptalk {
14	
15	parser::parser(const stomptalk_parser_config &config, stomptalk_frame_view *frames,
16	    stomptalk_header_view *headers, char *bytes, stomptalk_backend backend) noexcept
17	    : config_(config), frames_(frames), headers_(headers), bytes_(bytes, config.byte_capacity),
18	      backend_(backend) { reset(); }
19	
20	void parser::reset() noexcept {
21	    bytes_.reset();
22	    frame_count_ = header_used_ = header_begin_ = byte_begin_ = active_bytes_ = 0;
23	    current_ = {};
24	    key_ = token_ = {nullptr, 0};
25	    active_ = begun_ = escape_ = literal_ = length_header_ = token_owned_ = false;
26	    error_ = STOMPTALK_ERROR_NONE;
27	    status_ = STOMPTALK_PARSE_OK;
28	    error_offset_ = 0;
29	    begin_ = stop_ = nullptr;
30	    switch (backend_) {
31	    case STOMPTALK_BACKEND_SWAR: state_ = &parser::start_state<STOMPTALK_BACKEND_SWAR>; break;
32	#if STOMPTALK_SSE2
33	    case STOMPTALK_BACKEND_SSE2: state_ = &parser::start_state<STOMPTALK_BACKEND_SSE2>; break;
34	#endif
35	#if STOMPTALK_PARSER_AVX2
36	    case STOMPTALK_BACKEND_AVX2: state_ = avx2_state(); break;
37	#endif
38	    default: state_ = &parser::start_state<STOMPTALK_BACKEND_SCALAR>; break;
39	    }
40	}
41	
42	parser::pointer parser::fail(stomptalk_error_code error, pointer at) noexcept {
43	    error_ = error;
44	    status_ = STOMPTALK_PARSE_ERROR;
45	    error_offset_ = static_cast<size_t>(at - begin_);
46	    return stop_ = at + 1;
47	}
48	
49	// Reserve logical bytes, including borrowed active strings. Already completed
50	// records occupy [0, byte_begin_); reclaiming them must free this exact resource.
51	bool parser::reserve(size_t count, pointer at) noexcept {
52	    if (count > config_.byte_capacity - active_bytes_) {
53	        fail(STOMPTALK_ERROR_BYTE_LIMIT, at + (config_.byte_capacity - active_bytes_));
54	        return false;
55	    }
56	    if (count > config_.byte_capacity - byte_begin_ - active_bytes_) {
57	        assert(frame_count_ && byte_begin_);
58	        status_ = STOMPTALK_PARSE_OUTPUT_FULL;
59	        stop_ = at;
60	        return false;
61	    }
62	    active_bytes_ += count;
63	    return true;
64	}
65	
66	void parser::own(stomptalk_view &v) noexcept {
67	    if (!v.size) { v.data = nullptr; return; }
68	    const uintptr_t offset = reinterpret_cast<uintptr_t>(v.data) -
69	                             reinterpret_cast<uintptr_t>(bytes_.data());
70	    if (offset < config_.byte_capacity) return;
71	    char *dest = bytes_.next();
72	    const bool ok = bytes_.push(v.data, v.size);
73	    assert(ok); // space was reserved before the source bytes were consumed
74	    (void)ok;
75	    v.data = dest;
76	}
77	
78	void parser::own_metadata() noexcept {
79	    own(current_.method_text);
80	    for (size_t i = header_begin_; i < header_used_; ++i) {
81	        own(headers_[i].key);
82	        own(headers_[i].value);
83	    }
84	    own(key_);
85	}
86	
87	void parser::own_token() noexcept {
88	    if (token_owned_) return;
89	    own_metadata(); // the open string must remain last in the accumulator
90	    char *dest = bytes_.next();
91	    const bool ok = bytes_.push(token_.data, token_.size);
92	    assert(ok);
93	    (void)ok;
94	    token_.data = dest;
95	    token_owned_ = true;
96	}
97	
98	bool parser::append(pointer data, size_t count) noexcept {
99	    if (!count) return true;
100	    if (!reserve(count, data)) return false;
101	    if (token_owned_) {
102	        const bool ok = bytes_.push(data, count);
103	        assert(ok);
104	        (void)ok;
105	    } else if (!token_.size) {
106	        token_.data = data;
107	    } else {
108	        assert(token_.data + token_.size == data);
109	    }
110	    token_.size += count;
111	    return true;
112	}
113	
114	bool parser::append(char value, pointer source) noexcept {
115	    if (!reserve(1, source)) return false;
116	    own_token();
117	    const bool ok = bytes_.push(value);
118	    assert(ok);
119	    (void)ok;
120	    ++token_.size;
121	    return true;
122	}
123	
124	stomptalk_view parser::finish_token() noexcept {
125	    const stomptalk_view result = token_.size ? token_ : stomptalk_view{nullptr, 0};
126	    token_ = {nullptr, 0};
127	    token_owned_ = false;
128	    return result;
129	}
130	
131	void parser::recycle() noexcept {
132	    frame_count_ = 0;
133	    current_.payload = nullptr;
134	    current_.parsed.payload_size = 0;
135	    if (!active_) {
136	        bytes_.reset();
137	        header_used_ = header_begin_ = byte_begin_ = 0;
138	        return;
139	    }
140	    const size_t count = header_used_ - header_begin_;
141	    if (header_begin_ && count)
142	        std::memmove(headers_, headers_ + header_begin_, count * sizeof(*headers_));
143	    header_used_ = count;
144	    header_begin_ = 0;
145	    // All persistent active views were promoted before the preceding return.
146	    if (byte_begin_) {
147	        auto shift = [this](stomptalk_view &v) {
148	            if (v.data) v.data -= byte_begin_;
149	        };
150	        shift(current_.method_text);
151	        shift(key_);
152	        shift(token_);
153	        for (size_t i = 0; i < count; ++i) {
154	            shift(headers_[i].key);
155	            shift(headers_[i].value);
156	        }
157	        bytes_.retain(byte_begin_);
158	        byte_begin_ = 0;
159	    }
160	}
161	
162	void parser::publish(bool complete) noexcept {
163	    assert(frame_count_ < config_.frame_capacity);
164	    current_.headers = current_.parsed.header_count ? headers_ + header_begin_ : nullptr;
165	    current_.parsed.flags &= STOMPTALK_FRAME_HAS_CONTENT_LENGTH;
166	    if (!begun_) current_.parsed.flags |= STOMPTALK_FRAME_BEGIN;
167	    if (complete) current_.parsed.flags |= STOMPTALK_FRAME_COMPLETE;
168	    frames_[frame_count_++] = current_;
169	    current_.parsed.payload_offset += current_.parsed.payload_size;
170	    current_.payload = nullptr;
171	    current_.parsed.payload_size = 0;
172	    begun_ = true;
173	    if (complete) active_ = false;
174	}
175	
176	bool parser::finish_value(pointer eol) noexcept {
177	    const stomptalk_view value = finish_token();
178	    if (length_header_) {
179	        uint64_t length;
180	        if (!antoull(length, value.data, value.size)) {
181	            fail(STOMPTALK_ERROR_CONTENT_LENGTH, eol);
182	            return false;
183	        }
184	        if (length > config_.max_body_size) {
185	            fail(STOMPTALK_ERROR_BODY_LIMIT, eol);
186	            return false;
187	        }
188	        current_.parsed.content_length = length;
189	        current_.parsed.flags |= STOMPTALK_FRAME_HAS_CONTENT_LENGTH;
190	    }
191	    headers_[header_used_++] = {key_, value};
192	    ++current_.parsed.header_count;
193	    key_ = {nullptr, 0};
194	    length_header_ = false;
195	    return true;
196	}
197	
198	bool parser::check_body(size_t count, pointer source) noexcept {
199	    if (count > config_.max_body_size - current_.parsed.payload_offset) {
200	        fail(STOMPTALK_ERROR_BODY_LIMIT,
201	             source + static_cast<size_t>(config_.max_body_size - current_.parsed.payload_offset));
202	        return false;
203	    }
204	    return true;
205	}
206	
207	// Baseline states stay usable on CPUs without AVX2.
208	#define STOMPTALK_STATE_TARGET
209	#include "parser_states.hpp"
210	#undef STOMPTALK_STATE_TARGET
211	
212	stomptalk_parse_result parser::run(pointer data, size_t size) noexcept {
213	    if (error_) return {0, frames_, 0, STOMPTALK_PARSE_ERROR, error_, 0};
214	    recycle();
215	    status_ = STOMPTALK_PARSE_OK;
216	    error_offset_ = 0;
217	    if ((!data && size) || size > size_t(PTRDIFF_MAX)) {
218	        error_ = STOMPTALK_ERROR_ARGUMENT;
219	        return {0, frames_, 0, STOMPTALK_PARSE_ERROR, error_, 0};
220	    }
221	    pointer curr = data;
222	    begin_ = data;
223	    if (size) {
224	        const pointer end = data + size;
225	        while (curr < end && status_ == STOMPTALK_PARSE_OK)
226	            curr = (this->*state_)(curr, end);
227	    }
228	    if (status_ != STOMPTALK_PARSE_ERROR && active_) {
229	        // An owned open token already has all earlier metadata before it.
230	        // BEGIN is published only after promotion, so body continuations also
231	        // need no repeated walk of the same header views.
232	        if (!begun_) {
233	            if (token_.size || token_owned_) own_token();
234	            else own_metadata();
235	        }
236	        if (current_.parsed.payload_size) publish(false);
237	    }
238	    if (status_ == STOMPTALK_PARSE_OK) {
239	        const bool boundary = state_ == &parser::start_state<STOMPTALK_BACKEND_SCALAR> ||
240	                              state_ == &parser::start_state<STOMPTALK_BACKEND_SWAR>
241	#if STOMPTALK_SSE2
242	                              || state_ == &parser::start_state<STOMPTALK_BACKEND_SSE2>
243	#endif
244	#if STOMPTALK_PARSER_AVX2
245	                              || (backend_ == STOMPTALK_BACKEND_AVX2 && state_ == avx2_state())
246	#endif
247	                              ;
248	        if (!boundary) status_ = STOMPTALK_PARSE_NEED_INPUT;
249	    }
250	    const size_t consumed = size ? static_cast<size_t>(curr - data) : 0;
251	    begin_ = stop_ = nullptr;
252	    return {consumed, frames_, frame_count_, status_, error_, error_offset_};
253	}
254	}
