2	#pragma once
3	
4	template<stomptalk_backend B>
5	STOMPTALK_STATE_TARGET
6	parser::pointer parser::start_state(pointer curr, pointer end) noexcept {
7	    while (curr < end) {
8	        const unsigned char ch = static_cast<unsigned char>(*curr);
9	        if (ch == '\n') { ++curr; continue; }
10	        if (ch == '\r') return tailcall(&parser::start_cr<B>, curr + 1, end);
11	        if (ch < 'A' || ch > 'Z') return fail(STOMPTALK_ERROR_METHOD, curr);
12	        if (frame_count_ == config_.frame_capacity) {
13	            status_ = STOMPTALK_PARSE_OUTPUT_FULL;
14	            return curr;
15	        }
16	        current_ = {};
17	        key_ = token_ = {nullptr, 0};
18	        token_owned_ = escape_ = literal_ = length_header_ = begun_ = false;
19	        active_ = true;
20	        active_bytes_ = 0;
21	        byte_begin_ = bytes_.size();
22	        header_begin_ = header_used_;
23	        return tailcall(&parser::method_state<B>, curr, end);
24	    }
25	    return curr;
26	}
27	
28	template<stomptalk_backend B>
29	STOMPTALK_STATE_TARGET
30	parser::pointer parser::start_cr(pointer curr, pointer end) noexcept {
31	    if (*curr != '\n') return fail(STOMPTALK_ERROR_EOL, curr);
32	    return tailcall(&parser::start_state<B>, curr + 1, end);
33	}
34	
35	template<stomptalk_backend B>
36	STOMPTALK_STATE_TARGET
37	parser::pointer parser::method_state(pointer curr, pointer end) noexcept {
38	    pointer p = curr;
39	    // Short commands stay scalar; SIMD header scanning does not imply SIMD IDs.
40	    while (p < end && *p >= 'A' && *p <= 'Z') ++p;
41	    if (!append(curr, static_cast<size_t>(p - curr))) return stop_;
42	    if (p == end) return p;
43	    const char ch = *p;
44	    if (ch != '\n' && ch != '\r') return fail(STOMPTALK_ERROR_METHOD, p);
45	    current_.method_text = finish_token();
46	    current_.parsed.method_id = detail::detect_method(current_.method_text);
47	    literal_ = current_.parsed.method_id == STOMPTALK_METHOD_CONNECT ||
48	               current_.parsed.method_id == STOMPTALK_METHOD_CONNECTED;
49	    return ch == '\n' ? tailcall(&parser::hdrline_done<B>, p + 1, end)
50	                      : tailcall(&parser::hdrline_almost_done<B>, p + 1, end);
51	}
52	
53	template<stomptalk_backend B>
54	STOMPTALK_STATE_TARGET
55	parser::pointer parser::hdrline_done(pointer curr, pointer end) noexcept {
56	    if (*curr == '\n') return tailcall(&parser::done<B>, curr + 1, end);
57	    if (*curr == '\r') return tailcall(&parser::almost_done<B>, curr + 1, end);
58	    if (current_.parsed.header_count == config_.max_headers_per_frame)
59	        return fail(STOMPTALK_ERROR_HEADER_LIMIT, curr);
60	    if (header_used_ == config_.header_capacity) {
61	        assert(frame_count_ && header_begin_);
62	        status_ = STOMPTALK_PARSE_OUTPUT_FULL;
63	        return curr;
64	    }
65	    // The first byte goes through exactly the same decoder as all others.
66	    return tailcall(&parser::hdrline_hdr_key<B>, curr, end);
67	}
68	
69	template<stomptalk_backend B>
70	STOMPTALK_STATE_TARGET
71	parser::pointer parser::hdrline_hdr_key(pointer curr, pointer end) noexcept {
72	    while (curr < end) {
73	        if (escape_) {
74	            char ch = *curr;
75	            switch (ch) {
76	            case 'n': ch = '\n'; break;
77	            case 'r': ch = '\r'; break;
78	            case 'c': ch = ':'; break;
79	            case '\\': break;
80	            default: return fail(STOMPTALK_ERROR_ESCAPE, curr);
81	            }
82	            if (!append(ch, curr)) return stop_;
83	            escape_ = false;
84	            ++curr;
85	            continue;
86	        }
87	        const pointer p = detail::backend::engine<B>::scan_header(curr, end, true, literal_);
88	        // Copy/borrow the entire clean range, including all preceding SIMD blocks.
89	        if (!append(curr, static_cast<size_t>(p - curr))) return stop_;
90	        if (p == end) return p;
91	        if (*p == '\\' && !literal_) {
92	            own_token();
93	            escape_ = true;
94	            curr = p + 1;
95	            continue;
96	        }
97	        if (*p != ':' || !token_.size) return fail(STOMPTALK_ERROR_HEADER, p);
98	        key_ = finish_token();
99	        length_header_ = !(current_.parsed.flags & STOMPTALK_FRAME_HAS_CONTENT_LENGTH) &&
100	            detail::is_content_length<B>(key_);
101	        return tailcall(&parser::hdrline_val<B>, p + 1, end);
102	    }
103	    return curr;
104	}
105	
106	template<stomptalk_backend B>
107	STOMPTALK_STATE_TARGET
108	parser::pointer parser::hdrline_val(pointer curr, pointer end) noexcept {
109	    while (curr < end) {
110	        if (escape_) {
111	            char ch = *curr;
