5	#include <cassert>
6	#include <limits>
7	
8	namespace stomptalk {
9	namespace detail {
10	
11	template<std::size_t Size>
12	STOMPTALK_FORCE_INLINE
13	constexpr stomptalk_view name_view(const char (&text)[Size]) noexcept
